// Generated by LeagueBattleSim/tools/export_site.py from templates/page.html. Do not edit here.
const R = window.KALISTA.results;
const ED = window.KALISTA.editor;
const $ = id => document.getElementById(id);
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const pct = x => (x >= 0 ? "+" : "−") + Math.abs(x * 100).toFixed(0) + "%";
const f2 = x => Number(x).toFixed(2);
const GOALS = Object.keys(R.goals);
const COLORS = {kill:"var(--s1)", duel:"var(--s2)", practical:"var(--s3)", safe:"var(--s4)", carry:"var(--s5)"};
const TH = Object.keys(R.threats);
const TH_SHORT = {marksman:"M", bruiser:"B", tank:"T", mage:"Mg", Caitlyn:"Cait", Ezreal:"Ez", Lux:"Lux", Nautilus:"Naut"};
const NOTES = {
  kill: "Fastest kill against four dummies that don't fight back. This is the pure damage build.",
  duel: "Most HP left after one-on-one fights with each enemy. Guardian Angel's second life is included.",
  practical: "Same duel goal without Guardian Angel, the most realistic all-round build.",
  safe: "Longest time before Kalista dies. Maximum survival, at a big cost in damage.",
  carry: "Solo queue carry: single-target strength in 1v1s, 2v2s and 3v3s without giving up 5v5 teamfights (weights in config/teamfight.json)."
};
let goal = "practical", slot = 0;
try { const g = localStorage.getItem("kal-goal"); if (g && R.builds[g]) goal = g; } catch(e) {}

function avg(a){ return a.reduce((x,y)=>x+y,0)/a.length; }
// A matchup counts as won when the duel score (averaged over three enemy HP values) is positive.
function normalize(){
  const fix = o => { TH.forEach(t => { o.per[t].win = o.per[t].duel > 0; }); o.wins = TH.filter(t => o.per[t].win).length; };
  GOALS.forEach(g => { const b = R.builds[g]; b.path.forEach(fix); b.spikes.forEach(sp => { fix(sp.base); sp.ranking.forEach(fix); }); });
  R.ap.path.forEach(fix);
}
normalize();
function pills(per){ return TH.map(t => `<span class="pill ${per[t].win?"w":"l"}" title="${esc(R.threats[t])}: ${pct(per[t].duel)}">${(TH_SHORT[t] || t.slice(0, 4))} ${per[t].win?"W":"L"}</span>`).join(""); }

function renderGoals(){
  $("goals").innerHTML = GOALS.map(g => {
    const b = R.builds[g];
    const d = avg(b.path.map(p => p.duel)), wins = b.path.reduce((s,p)=>s+p.wins,0);
    return `<button class="goal" type="button" data-g="${g}" aria-pressed="${g===goal}"><span class="gname"><span class="swatch" style="background:${COLORS[g]}"></span>${esc(R.goals[g])}</span><span class="gsum">${esc(b.path.map(p=>p.item).slice(0,3).join(" → "))} …</span><span class="gsum mono">duel ${pct(d)} · ${wins}/20 wins</span></button>`;
  }).join("");
  [...$("goals").children].forEach(b => b.addEventListener("click", () => { goal = b.dataset.g; try{localStorage.setItem("kal-goal", goal);}catch(e){} render(); }));
}

function render(){
  renderGoals();
  const B = R.builds[goal];
  $("goalnote").textContent = NOTES[goal];
  $("buildtitle").textContent = R.goals[goal];
  $("buildmeta").innerHTML = `<span class="chip">Runes <b>${esc(B.page)}</b></span><span class="chip">Boots <b>${esc(B.boots)}</b> at item 2</span><span class="chip">Start Doran's Blade</span>`;
  $("path").innerHTML = B.path.map(p => `<div class="step"><span class="lvl">Item ${p.slot} · lvl ${p.level}</span><span class="name">${esc(p.item)}</span><span class="nums"><span>duel ${pct(p.duel)}</span><span>kill ${f2(p.kill)}s</span></span><span class="pills">${pills(p.per)}</span></div>`).join("");

  $("matrix").innerHTML = `<thead><tr><th>Enemy</th>${B.path.map(p=>`<th class="n">Item ${p.slot} · ${p.level}</th>`).join("")}</tr></thead><tbody>` +
    TH.map(t => `<tr><td>${esc(R.threats[t])}</td>${B.path.map(p => { const v = p.per[t]; return `<td class="hm ${v.win?"w":"l"}">${v.win?"W":"L"} ${pct(v.duel)}</td>`; }).join("")}</tr>`).join("") + "</tbody>";

  renderPower(); renderSlots(); renderSide(); renderTeam();
}

function renderTeam(){
  const B = R.builds[goal];
  if (!B.team) { $("teamsec").hidden = true; return; }
  const SC = Object.keys(R.team_scenarios || {});
  const cell = v => `<td class="hm ${v > 0.005 ? "w" : v < -0.005 ? "l" : ""}">${pct(v)}</td>`;
  $("team").innerHTML = `<thead><tr><th>Fight</th>${B.team.map(t=>`<th class="n">Item ${t.slot} · ${t.level}</th>`).join("")}</tr></thead><tbody>` +
    `<tr><td>1v1 duel (avg)</td>${B.team.map(t=>cell(t.duel)).join("")}</tr>` +
    SC.map(sc => `<tr><td>${esc(R.team_scenarios[sc])}</td>${B.team.map(t=>cell(t[sc])).join("")}</tr>`).join("") +
    `<tr><td><b>Carry score</b></td>${B.team.map(t=>cell(t.carry)).join("")}</tr>` +
    `<tr><td>5v5: Kalista's damage share</td>${B.team.map(t=>`<td class="n">${Math.round(t.share["5v5"]*100)}%</td>`).join("")}</tr>` +
    `<tr><td>5v5: Kalista survives</td>${B.team.map(t=>`<td class="n">${Math.round(t.alive["5v5"]*100)}%</td>`).join("")}</tr></tbody>`;
  const w = R.carry_weights || {};
  $("teamnote").textContent = "Score: your team's HP left if it wins, minus the enemy team's if it loses; each fight is averaged over Kalista hitting the frontline first and the backline first. Bruisers dive the carries, everyone else hits what is in front. Carry score = " +
    Object.entries(w).map(([k,v]) => `${Math.round(v*100)}% ${k === "duel" ? "duel" : k}`).join(" + ") + ".";
}

function renderPower(){
  const W=Math.max(360, $("pcbox").clientWidth - 24),H=260,L=46,Rr=122,T=14,Bt=34;
  $("pc").setAttribute("viewBox", `0 0 ${W} ${H}`);
  const all = GOALS.flatMap(g => R.builds[g].path.map(p => p.duel));
  let lo = Math.min(0, ...all), hi = Math.max(...all);
  lo = Math.floor(lo*10)/10; hi = Math.ceil(hi*10)/10;
  const x = i => L + i*(W-L-Rr)/4, y = v => T + (hi-v)/(hi-lo)*(H-T-Bt);
  let s = "";
  for (let v = lo; v <= hi + 1e-9; v += 0.1) {
    const yy = y(v).toFixed(1);
    s += `<line x1="${L}" x2="${W-Rr}" y1="${yy}" y2="${yy}" stroke="var(--grid)" stroke-width="${Math.abs(v)<1e-9?1.5:1}"/>`;
    s += `<text x="${L-6}" y="${+yy+4}" text-anchor="end">${pct(v)}</text>`;
  }
  if (lo < 0) s += `<line x1="${L}" x2="${W-Rr}" y1="${y(0)}" y2="${y(0)}" stroke="var(--muted)" stroke-width="1"/>`;
  R.builds.kill.path.forEach((p,i) => { s += `<text x="${x(i)}" y="${H-18}" text-anchor="middle">Item ${p.slot}</text><text x="${x(i)}" y="${H-5}" text-anchor="middle">lvl ${p.level}</text>`; });
  const ends = [];
  GOALS.forEach(g => {
    const pts = R.builds[g].path.map((p,i) => [x(i), y(p.duel)]);
    const w = g === goal ? 3 : 2, op = g === goal ? 1 : 0.55;
    s += `<polyline fill="none" stroke="${COLORS[g]}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" opacity="${op}" points="${pts.map(p=>p.join(",")).join(" ")}"/>`;
    pts.forEach((p,i) => { s += `<circle cx="${p[0]}" cy="${p[1]}" r="4.5" fill="${COLORS[g]}" stroke="var(--panel)" stroke-width="2" opacity="${op}"/>`; });
    ends.push([g, pts[4][1]]);
  });
  ends.sort((a,b)=>a[1]-b[1]); for (let i=1;i<ends.length;i++) if (ends[i][1]-ends[i-1][1] < 13) ends[i][1] = ends[i-1][1] + 13;
  ends.forEach(([g,yy]) => { s += `<text x="${W-Rr+8}" y="${yy+4}" style="fill:var(--ink)">${esc({kill:"Fastest kill",duel:"Duelist",practical:"No-GA duelist",safe:"Hardest to kill",carry:"Solo queue carry"}[g])}</text>`; });
  R.builds.kill.path.forEach((p,i) => { s += `<rect x="${x(i)-28}" y="${T}" width="56" height="${H-T-Bt}" fill="transparent" data-i="${i}" class="hit"/>`; });
  $("pc").innerHTML = s;
  $("pclegend").innerHTML = GOALS.map(g => `<span><span class="swatch" style="background:${COLORS[g]}"></span>${esc(R.goals[g])}</span>`).join("");
  const tip = $("pctip");
  $("pc").querySelectorAll(".hit").forEach(h => {
    h.addEventListener("mousemove", ev => {
      const i = +h.dataset.i;
      tip.innerHTML = `<b>Item ${i+1}</b><br>` + GOALS.map(g => `${esc(R.goals[g])}: ${pct(R.builds[g].path[i].duel)} · ${R.builds[g].path[i].wins}/4 wins`).join("<br>");
      place(tip, $("pcbox"), ev);
    });
    h.addEventListener("mouseleave", () => tip.hidden = true);
  });
}

function place(tip, box, ev){
  tip.hidden = false;
  const r = box.getBoundingClientRect();
  let lx = ev.clientX - r.left + 12, ly = ev.clientY - r.top + 12;
  if (lx + 250 > r.width) lx = ev.clientX - r.left - 250;
  tip.style.left = Math.max(4, lx) + "px"; tip.style.top = ly + "px";
}

function renderSlots(){
  const B = R.builds[goal];
  $("slots").innerHTML = B.spikes.map((s,i) => `<button role="tab" type="button" aria-selected="${i===slot}">Item ${s.slot} · lvl ${s.level}</button>`).join("");
  [...$("slots").children].forEach((b,i) => b.addEventListener("click", () => { slot = i; renderSlots(); }));
  const sp = B.spikes[slot], pick = B.path[slot].item;
  $("owned").textContent = `Level ${sp.level} · you own ${sp.owned.join(", ")} · enemies have ${sp.enemy_items} item${sp.enemy_items>1?"s":""} · without a new item your duel score is ${pct(sp.base.duel)}.`;
  const rows = sp.ranking;
  $("rank").innerHTML = `<thead><tr><th class="n">#</th><th>Item</th><th class="n">Duel</th><th class="n">Δ duel</th><th class="n">Kill</th><th class="n">Faster</th><th class="n">Alive</th><th class="n">Wins</th>${TH.map(t=>`<th class="n">${(TH_SHORT[t] || t.slice(0, 4))}</th>`).join("")}<th class="n">Cost</th></tr></thead><tbody>` +
    rows.map(r => `<tr class="${r.item===pick?"pick":""}"><td class="n">${r.rank}</td><td class="${r.item==="Riftmaker"?"rift":""}">${esc(r.item)}</td><td class="n">${pct(r.duel)}</td><td class="n">${r.duel_gain>=0?"+":""}${r.duel_gain.toFixed(1)}</td><td class="n">${f2(r.kill)}s</td><td class="n">${r.faster_pct.toFixed(0)}%</td><td class="n">${f2(r.safe)}s</td><td class="n">${r.wins}/4</td>${TH.map(t=>`<td class="n ${r.per[t].win?"cw":"cl"}">${pct(r.per[t].duel)}</td>`).join("")}<td class="n">${r.cost}</td></tr>`).join("") + "</tbody>";
  renderScatter(sp, pick);
  renderFight();
}

function renderScatter(sp, pick){
  const W=Math.max(360, $("scbox").clientWidth - 24),H=300,L=48,Rr=16,T=14,Bt=40;
  $("sc").setAttribute("viewBox", `0 0 ${W} ${H}`);
  const rows = sp.ranking;
  const xs = rows.map(r=>r.kill), ys = rows.map(r=>r.duel);
  let x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  const px = (x1-x0)*0.06||0.1, py = (y1-y0)*0.08||0.02; x0-=px; x1+=px; y0-=py; y1+=py;
  // x reversed: faster kill (lower time) on the right
  const X = v => L + (x1-v)/(x1-x0)*(W-L-Rr), Y = v => T + (y1-v)/(y1-y0)*(H-T-Bt);
  let s = "";
  const yt = niceTicks(y0,y1,5), xt = niceTicks(x0,x1,6);
  yt.forEach(v => { s += `<line x1="${L}" x2="${W-Rr}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--grid)"/><text x="${L-6}" y="${Y(v)+4}" text-anchor="end">${pct(v)}</text>`; });
  xt.forEach(v => { s += `<line y1="${T}" y2="${H-Bt}" x1="${X(v)}" x2="${X(v)}" stroke="var(--grid)"/><text x="${X(v)}" y="${H-Bt+16}" text-anchor="middle">${v.toFixed(1)}s</text>`; });
  s += `<text x="${(L+W-Rr)/2}" y="${H-6}" text-anchor="middle">Kill time (faster →)</text>`;
  const order = [...rows].sort((a,b) => (a.item===pick) - (b.item===pick) || (a.item==="Riftmaker") - (b.item==="Riftmaker"));
  order.forEach(r => {
    const isPick = r.item===pick, isRift = r.item==="Riftmaker";
    const fill = isPick ? "var(--spirit)" : isRift ? "var(--gold)" : "var(--muted)";
    const op = isPick || isRift ? 1 : 0.45;
    s += `<circle cx="${X(r.kill)}" cy="${Y(r.duel)}" r="${isPick?7:5}" fill="${fill}" opacity="${op}" stroke="var(--panel)" stroke-width="2"/>`;
    s += `<circle cx="${X(r.kill)}" cy="${Y(r.duel)}" r="12" fill="transparent" class="hit" data-n="${esc(r.item)}" data-k="${r.kill}" data-d="${r.duel}" data-w="${r.wins}" data-r="${r.rank}"/>`;
  });
  // direct labels: pick, Riftmaker, top 3 by goal
  const lab = new Set([pick, "Riftmaker", ...rows.slice(0,3).map(r=>r.item)]);
  rows.filter(r => lab.has(r.item)).forEach(r => {
    const xx = X(r.kill), right = xx > W*0.55;
    s += `<text x="${xx + (right?-10:10)}" y="${Y(r.duel)-8}" text-anchor="${right?"end":"start"}" style="fill:var(--ink)">${esc(r.item)}</text>`;
  });
  $("sc").innerHTML = s;
  const tip = $("sctip");
  $("sc").querySelectorAll(".hit").forEach(h => {
    h.addEventListener("mousemove", ev => { const d = h.dataset;
      tip.innerHTML = `<b>${d.n}</b> (#${d.r})<br>Kill ${(+d.k).toFixed(2)}s · duel ${pct(+d.d)} · ${d.w}/4 wins`; place(tip, $("scbox"), ev); });
    h.addEventListener("mouseleave", () => tip.hidden = true);
  });
}

function niceTicks(a,b,n){
  const span = b-a, step0 = span/n, mag = Math.pow(10, Math.floor(Math.log10(step0)));
  const step = [1,2,2.5,5,10].map(m=>m*mag).find(s => span/s <= n) || 10*mag;
  const out = []; for (let v = Math.ceil(a/step)*step; v <= b+1e-9; v += step) out.push(+v.toFixed(6));
  return out;
}

function renderFight(){
  const B = R.builds[goal], p = B.path[slot], br = p.breakdown;
  $("fightlede").textContent = `With ${p.item} at item ${p.slot} (level ${p.level}): where Kalista's damage taken and healing came from in each duel.`;
  const srcs = s => Object.entries(s).sort((a,b)=>b[1]-a[1]).map(([k,v]) => `${esc(k)} ${v}`).join(" · ") || "—";
  $("fight").innerHTML = `<thead><tr><th>Enemy</th><th>Result</th><th class="n">Kill</th><th>Damage taken</th><th>Healing and shields</th></tr></thead><tbody>` +
    TH.map(t => { const v = p.per[t], b = br[t];
      return `<tr><td>${esc(R.threats[t])}</td><td class="${v.win?"cw":"cl"}">${v.win?"Won":"Lost"} ${pct(v.duel)}${b.ga_used?" (GA used)":""}</td><td class="n">${f2(v.tk)}s</td><td>${srcs(b.taken_by)}</td><td>${srcs(b.healed_by)}</td></tr>`; }).join("") + "</tbody>";
}

function renderSide(){
  const B = R.builds[goal];
  const ups = [...new Set(B.kite.map(k=>k.uptime))];
  $("kite").innerHTML = `<thead><tr><th>Melee lands</th>${B.path.map(p=>`<th class="n">Item ${p.slot}</th>`).join("")}</tr></thead><tbody>` +
    ups.map(u => `<tr class="${u===0.65?"pick":""}"><td class="mono">${Math.round(u*100)}%</td>${B.kite.filter(k=>k.uptime===u).map(k=>`<td class="n ${k.wins===4?"cw":"cl"}">${pct(k.duel)} · ${k.wins}/4</td>`).join("")}</tr>`).join("") + "</tbody>";
  const best = B.pages[0].score;
  const higher = goal !== "kill";
  $("pages").innerHTML = `<thead><tr><th>Page</th><th class="n">vs best</th></tr></thead><tbody>` +
    B.pages.slice(0,8).map((p,i) => { const d = higher ? (p.score/best - 1) * -100 : (p.score/best - 1) * 100;
      return `<tr class="${i===0?"pick":""}"><td>${esc(p.page)}</td><td class="n">${i===0?"best":(higher?"−":"+")+Math.abs(d).toFixed(1)+"%"}</td></tr>`; }).join("") + "</tbody>";
}

function renderStatic(){
  $("cross").innerHTML = `<thead><tr><th>Build</th><th class="n">Kill time</th><th class="n">Duel score</th><th class="n">Time alive</th><th class="n">Duel wins</th><th class="n">Carry score</th></tr></thead><tbody>` +
    GOALS.map(g => { const c = R.cross[g], b = R.builds[g];
      return `<tr><td><span class="swatch" style="display:inline-block;background:${COLORS[g]};margin-right:6px"></span>${esc(R.goals[g])}</td><td class="n">${f2(avg(c.map(x=>x.kill)))}s</td><td class="n">${pct(avg(c.map(x=>x.duel)))}</td><td class="n">${f2(avg(c.map(x=>x.safe)))}s</td><td class="n">${b.path.reduce((s,p)=>s+p.wins,0)}/20</td><td class="n">${c[0].carry == null ? "—" : pct(avg(c.map(x=>x.carry)))}</td></tr>`; }).join("") + "</tbody>";

  $("ap").innerHTML = `<thead><tr><th>Spike</th><th>Item</th><th class="n">AP duel</th><th class="n">No-GA build</th></tr></thead><tbody>` +
    R.ap.path.map((p,i) => `<tr><td class="mono">${p.slot} · lvl ${p.level}</td><td>${esc(p.item)}</td><td class="n">${pct(p.duel)}</td><td class="n">${pct(R.ap.vs_best[i].best_duel)}</td></tr>`).join("") + "</tbody>";
  const rf = R.riftmaker;
  $("rift").innerHTML = `<thead><tr><th>Goal</th>${[1,2,3,4,5].map(s=>`<th class="n">Item ${s}</th>`).join("")}</tr></thead><tbody>` +
    GOALS.map(g => `<tr><td>${esc(R.goals[g])}</td>${[1,2,3,4,5].map(s => { const x = rf.find(z=>z.goal===g&&z.slot===s);
      return `<td class="n">${x.rank==null?"owned":x.rank+" / "+x.of}</td>`; }).join("")}</tr>`).join("") + "</tbody>";
  $("apnote").textContent = `AP Kalista (${R.ap.page}, ${R.ap.boots}) wins duels but trails the no-GA build at every spike after the first. Riftmaker only ranks near the top when the goal is survival, because its value is health and omnivamp rather than damage.`;
  const c = R.calibration;
  $("calib").textContent = "Enemy damage is calibrated: each enemy's damage is multiplied by one fixed number (" +
    TH.map(t => c[t] ? `${R.threats[t].toLowerCase()} ×${c[t].mult}` : `${R.threats[t]} (real kit, uncalibrated)`).join(", ") +
    ") so a standard crit Kalista (Yun Tal → IE → LDR → Stormrazor → BotRK) narrowly wins on average. The multiplier never changes between spikes, so early and late power shifts still show.";
}

function renderLane(){
  const Ln = R.lane, LT = Object.keys(Ln.threats), P = Ln.lane_path;
  const LS = {marksman:"ADC", mage:"Mage sup", tank:"Tank sup", Caitlyn:"Cait", Ezreal:"Ez", Lux:"Lux", Nautilus:"Naut"};
  const sgn = x => (x >= 0 ? "+" : "−") + Math.abs(x*100).toFixed(1) + "%";
  const cls = x => x > 0.005 ? "cw" : x < -0.005 ? "cl" : "";
  $("lanemeta").innerHTML = `<span class="chip">Runes <b>${esc(P.page)}</b></span><span class="chip">Items <b>${esc(P.items.join(" → "))}</b></span><span class="chip">Boots <b>${esc(P.boots)}</b> at item 2</span>`;
  $("lanestages").innerHTML = `<thead><tr><th>Stage</th><th class="n">Quick</th><th class="n">Extended</th><th class="n">Kill pressure</th>${LT.map(t=>`<th class="n">${LS[t]} quick</th>`).join("")}${LT.map(t=>`<th class="n">${LS[t]} execute</th>`).join("")}</tr></thead><tbody>` +
    P.stages.map(s => `<tr><td>${esc(s.stage)}</td><td class="n ${cls(s.trade)}">${sgn(s.trade)}</td><td class="n ${cls(s.long)}">${sgn(s.long)}</td><td class="n">${Math.round(s.pressure*100)}% HP</td>${LT.map(t=>`<td class="n ${cls(s.per[t].trade)}">${sgn(s.per[t].trade)}</td>`).join("")}${LT.map(t=>{const e=s.per[t].exec; return `<td class="n ${e.killed?"cw":"cl"}">${e.killed?(e.time.toFixed(2)+"s"):"escaped"}</td>`;}).join("")}</tr>`).join("") + "</tbody>";

  const top = Ln.runes[0];
  const quickBest = [...Ln.runes].sort((a,b)=>b.trade-a.trade)[0];
  $("runenote").textContent = `Scored at levels 2, 3 and 6 on Doran's Blade. Kalista fits only two autos into a 2-second trade early, so Press the Attack (three hits) and Lethal Tempo (stacks) rarely fire in quick trades: ${quickBest.page.split(" / ")[0]} wins those narrowly, while Press the Attack wins extended trades by far more.`;
  $("lanerunes").innerHTML = `<thead><tr><th>Page</th><th class="n">Lane score</th><th class="n">Quick</th><th class="n">Extended</th><th class="n">Kill pressure</th></tr></thead><tbody>` +
    Ln.runes.slice(0,10).map((p,i) => `<tr class="${i===0?"pick":""}"><td>${esc(p.page)}</td><td class="n">${(p.score*100).toFixed(1)}</td><td class="n ${cls(p.trade)}">${sgn(p.trade)}</td><td class="n ${cls(p.long)}">${sgn(p.long)}</td><td class="n">${Math.round(p.pressure*100)}%</td></tr>`).join("") + "</tbody>";

  const lists = [["first","Item 1 · lvl 9"],["second","Item 2 · lvl 11"]];
  let li = 0, sortKey = "score", sortDir = -1;
  function drawItems(){
    $("lanetabs").innerHTML = lists.map(([k,lab],i) => `<button role="tab" type="button" aria-selected="${i===li}">${lab}</button>`).join("");
    [...$("lanetabs").children].forEach((b,i) => b.addEventListener("click", () => { li = i; drawItems(); }));
    const D = Ln[lists[li][0]], pick = P.items[li];
    $("lanebase").textContent = `Without a new item: quick ${sgn(D.base.trade)}, extended ${sgn(D.base.long)}, kill pressure ${Math.round(D.base.pressure*100)}%.` + (li===1 ? " Boots shown are the best of Berserker's, Steelcaps or Mercury's for each item." : "");
    const cols = [["rank","#","n"],["item","Item",""],["score","Lane score","n"],["trade","Quick","n"],["long","Extended","n"],["pressure","Kill pressure","n"],["exec_cost","Execute cost","n"],["cost","Gold","n"]];
    if (li===1) cols.splice(2,0,["boots","Boots",""]);
    const rows = [...D.ranking].sort((a,b) => { const x=a[sortKey], y=b[sortKey]; return (typeof x==="string" ? x.localeCompare(y) : x-y) * sortDir * (sortKey==="rank"||sortKey==="exec_cost"||sortKey==="cost"||sortKey==="item"||sortKey==="boots" ? -1 : 1); });
    $("laneitems").innerHTML = `<thead><tr>${cols.map(([k,l,c])=>`<th class="${c}"><button type="button" data-k="${k}" style="all:unset;cursor:pointer">${l}${sortKey===k?(sortDir<0?" ↓":" ↑"):""}</button></th>`).join("")}</tr></thead><tbody>` +
      rows.map(r => `<tr class="${r.item===pick?"pick":""}">${cols.map(([k,,c]) => {
        let v = r[k];
        if (k==="score") v = (v*100).toFixed(1);
        else if (k==="trade"||k==="long") return `<td class="n ${cls(v)}">${sgn(v)}</td>`;
        else if (k==="pressure") v = Math.round(v*100)+"%";
        else if (k==="exec_cost") v = (v>=0?"":"+") + Math.round(-v*100) + "% HP";
        else if (k==="item") return `<td class="${r.item==="Riftmaker"?"rift":""}">${esc(v)}</td>`;
        return `<td class="${c}">${esc(v ?? "")}</td>`; }).join("")}</tr>`).join("") + "</tbody>";
    $("laneitems").querySelectorAll("th button").forEach(b => b.addEventListener("click", () => {
      const k = b.dataset.k; if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = -1; } drawItems(); }));
  }
  drawItems();

  $("lanegoals").innerHTML = `<thead><tr><th>Build</th><th>First two items</th><th class="n">Lvl 9 quick</th><th class="n">Lvl 9 ext.</th><th class="n">Lvl 11 quick</th><th class="n">Lvl 11 ext.</th><th class="n">Lvl 11 pressure</th></tr></thead><tbody>` +
    `<tr class="pick"><td>Lane build</td><td>${esc(P.items.join(", "))}</td>${[3,4].map(i=>`<td class="n ${cls(P.stages[i].trade)}">${sgn(P.stages[i].trade)}</td><td class="n ${cls(P.stages[i].long)}">${sgn(P.stages[i].long)}</td>`).join("")}<td class="n">${Math.round(P.stages[4].pressure*100)}%</td></tr>` +
    Ln.goal_builds.map(g => `<tr><td>${esc(g.name)}</td><td>${esc(g.items.join(", "))}</td>${[3,4].map(i=>`<td class="n ${cls(g.stages[i].trade)}">${sgn(g.stages[i].trade)}</td><td class="n ${cls(g.stages[i].long)}">${sgn(g.stages[i].long)}</td>`).join("")}<td class="n">${Math.round(g.stages[4].pressure*100)}%</td></tr>`).join("") + "</tbody>";
  const c = Ln.calibration;
  $("lanecal").textContent = "Lane enemies are calibrated separately from full fights: each one's damage is scaled (" + LT.map(t=>c[t].check === null ? `${Ln.threats[t]} real kit, uncalibrated` : `${Ln.threats[t].toLowerCase()} ×${c[t].mult}`).join(", ") + ") so a standard Kalista (Doran's Blade, Press the Attack / Alacrity / Cut Down) trades exactly even across levels 2, 3 and 6. Each build uses its own runes and boots.";
}

// ---------------------------------------------------------------- build editor (Pyodide)
const PYODIDE = "https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.js";
let py = null, edTimer = null;
const ITEM_ID = Object.fromEntries(Object.entries(ED.items).map(([id, n]) => [n, id]));
function loadScript(src){ return new Promise((ok, no) => { const s = document.createElement("script"); s.src = src; s.onload = ok; s.onerror = () => no(new Error("could not load " + src)); document.head.appendChild(s); }); }
function opt(v, label, sel){ return `<option value="${esc(v)}"${sel ? " selected" : ""}>${esc(label)}</option>`; }

function presets(){
  const out = [];
  GOALS.forEach(g => { const b = R.builds[g]; b.path.forEach(p => out.push({label: `${R.goals[g]} · item ${p.slot} (lvl ${p.level})`, goal: g, slot: p.slot, level: p.level, page: b.page, boots: b.boots, names: b.path.slice(0, p.slot).map(x => x.item)})); });
  const L = R.lane.lane_path;
  R.lane.lane_path.stages.forEach((st, i) => { const n = ED.lane_stages[i][2]; out.push({label: `Lane build · ${st.stage}`, slot: n, level: ED.lane_stages[i][1], page: L.page, boots: L.boots, names: L.items.slice(0, n), lane: true}); });
  return out;
}
const PRESETS = presets();
function inventoryIds(p){
  const ids = p.names.map(n => ITEM_ID[n]);
  if (p.slot >= 2 && p.boots) ids.push(ITEM_ID[p.boots]);
  if (p.slot <= 4) ids.push(ED.starter);
  return ids;
}
function setupForm(){
  $("edpreset").innerHTML = PRESETS.map((p, i) => opt(i, p.label, p.goal === goal && p.slot === 3)).join("");
  $("edne").innerHTML = opt("auto", "Same as yours", true) + [0,1,2,3,4,5].map(n => opt(n, n)).join("");
  $("edch").innerHTML = ED.champions.map(c => opt(c, c, c === (R.champion || "Kalista"))).join("");
  $("edsec").innerHTML = [0,1,2,3,4].map(n => opt(n, n === 0 ? "None (one target)" : n)).join("");
  $("edks").innerHTML = ED.keystones.map(k => opt(k, k)).join("");
  $("edlg").innerHTML = ED.legends.map(k => opt(k, k)).join("");
  $("edcb").innerHTML = ED.combat.map(k => opt(k, k)).join("");
  const names = Object.entries(ED.items).sort((a, b) => a[1].localeCompare(b[1]));
  $("eitems").innerHTML = [1,2,3,4,5,6].map(i => `<label>Slot ${i}<select data-slot="${i}">${opt("", "— empty —")}${names.map(([id, n]) => opt(id, n)).join("")}</select></label>`).join("");
  $("edkite").value = ED.kite;
  applyPreset(+$("edpreset").value);
  $("edform").querySelectorAll("select,input").forEach(el => el.addEventListener("input", () => { if (el.id === "edpreset") applyPreset(+el.value); scheduleRun(); }));
}
function applyPreset(i){
  const p = PRESETS[i], ids = inventoryIds(p), [ks, lg, cb] = p.page.split(" / ");
  $("eitems").querySelectorAll("select").forEach((s, j) => s.value = ids[j] || "");
  $("edlevel").value = p.level; $("edks").value = ks; $("edlg").value = lg; $("edcb").value = cb;
  $("edstacks").value = ED.legend[p.slot]; $("edne").value = "auto";
}
function scheduleRun(){ clearTimeout(edTimer); edTimer = setTimeout(runEditor, 120); }

async function startEngine(){
  const btn = $("edstart"), st = $("edstatus");
  btn.disabled = true; st.textContent = "Loading Python…";
  try {
    if (!window.loadPyodide) await loadScript(PYODIDE);
    py = await loadPyodide();
    st.textContent = "Loading the simulator…";
    // Inline in kalista_spikes.html; a site copy (tools/export_site.py) fetches it from data-src instead.
    const ef = $("engine-files");
    const files = ef.dataset.src ? await (await fetch(ef.dataset.src)).json() : JSON.parse(ef.textContent);
    for (const [path, text] of Object.entries(files)) {
      const parts = ("sim/" + path).split("/"); let dir = "";
      for (const d of parts.slice(0, -1)) { dir += "/" + d; try { py.FS.mkdir(dir); } catch(e) {} }
      py.FS.writeFile("/" + parts.join("/"), text);
    }
    py.runPython("import sys, json\nsys.path.insert(0, '/sim')\nfrom lolsim.editor import evaluate_build");
    $("edload").hidden = true; $("edform").hidden = false;
    setupForm(); runEditor();
  } catch (e) {
    btn.disabled = false; st.textContent = "Could not load the simulator (" + e.message + "). Check your connection, or use `./kalista build` locally.";
  }
}
$("edstart").addEventListener("click", startEngine);

function runEditor(){
  if (!py) return;
  const items = [...$("eitems").querySelectorAll("select")].map(s => s.value).filter(Boolean);
  const ne = $("edne").value;
  $("edlvlout").textContent = $("edlevel").value; $("edstout").textContent = $("edstacks").value;
  $("edkiteout").textContent = Math.round($("edkite").value * 100) + "%";
  const args = {items, level: +$("edlevel").value, page: [$("edks").value, $("edlg").value, $("edcb").value].join(" / "),
    stacks: +$("edstacks").value, enemy_items: ne === "auto" ? null : +ne,
    duel_mults: Object.fromEntries(Object.keys(R.calibration).map(t => [t, R.calibration[t].mult])),
    threats: TH, lane_threats: R.lane.threats,
    lane_mults: Object.fromEntries(Object.keys(R.lane.calibration).map(t => [t, R.lane.calibration[t].mult])),
    kite: +$("edkite").value, champion: $("edch").value, soul_mark: $("edsoul").value === "1", secondary: +$("edsec").value};
  let r;
  try { py.globals.set("args_json", JSON.stringify(args)); r = JSON.parse(py.runPython("json.dumps(evaluate_build(**json.loads(args_json)))")); }
  catch (e) { $("edwarn").hidden = false; $("edwarn").textContent = "Simulator error: " + e.message.split("\n").slice(-2).join(" "); return; }
  $("edwarn").hidden = !r.warnings.length; $("edwarn").textContent = r.warnings.join(" ");
  $("edstats").innerHTML = Object.entries(r.stats).filter(([k]) => k !== "level").map(([k, v]) => `<span class="chip">${esc(k)} <b>${esc(v)}</b></span>`).join("");
  const sg = x => (x >= 0 ? "+" : "−") + Math.abs(x * 100).toFixed(1) + "%";
  const sec = r.secondary > 0;
  $("edfights").innerHTML = `<thead><tr><th>Enemy</th><th class="n">Kill time</th>${sec ? `<th class="n">To ${r.secondary} other${r.secondary > 1 ? "s" : ""}</th>` : ""}<th>Duel</th><th class="n">Kill</th><th class="n">Death</th><th>Damage taken</th></tr></thead><tbody>` +
    Object.entries(r.fights).map(([t, f]) => `<tr><td>${esc(R.threats[t] || t)}</td><td class="n">${f.ttk == null ? "—" : f2(f.ttk) + "s"}</td>${sec ? `<td class="n" title="${esc(Object.entries(f.splash_by || {}).map(([k, v]) => k + " " + v).join(", "))}">${Math.round(f.splash || 0)}</td>` : ""}<td class="${f.win ? "cw" : "cl"}">${f.win ? "Won, " + Math.round(f.kal_hp_left * 100) + "% HP left" : "Lost, enemy on " + Math.round(f.enemy_hp_left * 100) + "%"}</td><td class="n">${f2(f.tk)}s</td><td class="n">${f.td >= 99 ? "—" : f2(f.td) + "s"}</td><td>${Object.entries(f.taken_by).sort((a, b) => b[1] - a[1]).map(([k, v]) => esc(k) + " " + v).join(" · ") || "—"}</td></tr>`).join("") + "</tbody>";
  $("edlane").innerHTML = `<thead><tr><th>Lane enemy</th><th class="n">Quick trade</th><th class="n">Extended</th><th class="n">Kill pressure</th></tr></thead><tbody>` +
    Object.entries(r.lane).map(([t, l]) => `<tr><td>${esc(R.lane.threats[t] || t)}</td><td class="n ${l.quick > 0.005 ? "cw" : l.quick < -0.005 ? "cl" : ""}">${sg(l.quick)}</td><td class="n ${l.long > 0.005 ? "cw" : l.long < -0.005 ? "cl" : ""}">${sg(l.long)}</td><td class="n">${Math.round(l.pressure * 100)}% HP</td></tr>`).join("") + "</tbody>";
  $("edteam").innerHTML = `<thead><tr><th>Team fight</th><th class="n">Score</th><th class="n">Kalista's share</th><th class="n">Survives</th><th class="n">Kills</th></tr></thead><tbody>` +
    Object.values(r.team).map(t => `<tr><td>${esc(t.label)}</td><td class="n ${t.score > 0.005 ? "cw" : t.score < -0.005 ? "cl" : ""}">${pct(t.score)}</td><td class="n">${Math.round(t.share*100)}%</td><td class="n">${Math.round(t.alive*100)}%</td><td class="n">${t.kills.toFixed(1)}</td></tr>`).join("") + "</tbody>";
  $("ednote").textContent = `${r.champion} at level ${r.level} against enemies with ${r.enemy_items} item${r.enemy_items === 1 ? "" : "s"}.` +
    (r.champion !== "Kalista" ? " Enemies stay calibrated against Kalista, so this compares champions on the same fights." : "") +
    (sec ? ` Damage to other enemies counts Runaan's bolts, Statikk's chain and Rend on their spears while killing the main target; it is not part of any score.` : "") +
    " Lane enemies are calibrated for levels 2–11; later levels are a stress test, not a lane read.";
}

renderStatic(); render(); renderLane();
